def ech(rows):
 P={}
 for v in rows:
  while v:
   i=v.bit_length()-1
   if i in P:v^=P[i]
   else:P[i]=v;break
 return P

def null(P,n):
 K=[]
 for j in range(n):
  if j in P:continue
  b=1<<j
  for i in sorted(P):
   if (b&P[i]).bit_count()%2:b^=1<<i
  K.append(b)
 return K

def ev(v):
 b=0
 for j,c in enumerate(C):
  if v>>j&1:b^=c
