 print(k,first);samples.setdefault(k,(v,K));st[k]+=1
 if all(st[k]>=20 for k in (15,17,20)):break
pickle.dump(samples,open('workspace/agent2_hermitian_Ksamples.pkl','wb'))
print('time',time.time()-start)

